const cds = require('../../../lib')

// Does the bound db serialize Int64/Decimal as strings? sqlite/postgres only under
// features.ieee754compatible; HANA and 3rd-party adapters always. Fixed after bootstrap.
let _asStrings
function providedAsStrings() {
  _asStrings ??= cds.db?.kind in { sqlite: 1, postgres: 1 } ? !!cds.env.features.ieee754compatible : true
  return _asStrings
}

// cds^9: opt-in — label only when explicitly opted in (=== true) AND the db actually serializes
// Int64/Decimal as strings, so the header never misrepresents the payload. A custom handler that
// already set Content-Type wins.
module.exports = function handle_ieee754(req, result) {
  if (cds.env.odata.ieee754compatible !== true) return //> no opt-in
  if (req.res.get('Content-Type')) return //> set by custom handler
  if (result == null || !providedAsStrings()) return

  req.res.set('Content-Type', 'application/json; charset=utf-8; IEEE754Compatible=true')
}
